// V.1_63 test fixture: a 60-slide-like proposal plan: the slide shapes Gemini wrote in deck 35 (ZoomInfo), as far as the output shows them
const P=(n,w)=>Array.from({length:n},(_,i)=>w[i%w.length]);
const sent=(k)=>['Request-driven access queues delay business analysis by weeks','Departmental data silos carry conflicting logic across sales and finance','Opaque data lineage erodes executive trust in reported numbers','Duplicated transformation scripts are rebuilt for single-use dashboards'].slice(0,k);
function plan(){
  const S=[];
  const add=(o)=>S.push(Object.assign({deckLibrary:'proposal',lead:'A short lead line that explains the slide in one sentence.',notes:'n'},o));
  const cards=(t,k)=>add({type:'cards',title:t,items:Array.from({length:k},(_,i)=>({title:'Capability '+(i+1),text:'One or two sentences that explain this capability and why it matters to the client teams.'}))});
  const proc=(t,k)=>add({type:'process',title:t,items:Array.from({length:k},(_,i)=>({title:'Step '+(i+1),text:'One sentence that says what happens in this step of the work.'}))});
  // fillers that use up designs, like a long deck does
  for(let i=0;i<10;i++){cards('Cards slide '+i,3+(i%4));proc('Process slide '+i,3+(i%3));}
  add({type:'stats',title:'Target engineering velocity',items:[{value:'100%',label:'data product freshness SLA'},{value:'75%',label:'fewer P1 quality incidents'},{value:'4x',label:'faster source onboarding'},{value:'50%',label:'shorter deployment lead time'}]});
  // the slides that came out as plain bullets
  add({type:'bullets',title:'Siloed reporting versus consumable data products',items:[{title:'Legacy approach',points:sent(4)},{title:'Target state',points:sent(3)}]});
  add({type:'comparison',title:'Ad-hoc scripting versus standardized DataOps',left:{title:'Legacy approach',points:sent(3)},right:{title:'Target state',points:sent(3)}});
  add({type:'bullets',title:'Scope: what is in and what is out',items:[{title:'In scope',points:sent(4)},{title:'Out of scope',points:sent(3)}]});
  add({type:'stats',title:'Projected total cost of ownership trajectory',items:[{value:'40%',label:'operating cost reduction',text:'Projected savings from retiring legacy licenses.'},{value:'60%',label:'remediation effort reduction',text:'Fewer hours fixing broken pipelines.'},{value:'35%',label:'faster issue resolution',text:'Shorter time to troubleshoot anomalies.'}]});
  add({type:'bullets',title:'The rising risk of unmanaged technical debt',items:[{title:'Disparate analytics sprawl',text:'Unmonitored tools create fragmented pipelines.',points:['Establish standardized blueprints','Enforce infrastructure as code']},{title:'Complex pipeline incidents',text:'Silent failures corrupt reporting.',points:['Automated observability','Self-healing ingestion']},{title:'Unclear data ownership',text:'No executive alignment.',points:['Define ownership roles','Form a steering committee']}]});
  add({type:'team',title:'Joint delivery team and governance structure',teams:[{name:'ZoomInfo team',roles:['Executive sponsor: approves scope','Domain data product owners: define KPIs']},{name:'66degrees team',roles:['Engagement lead: sprint delivery','Principal architect: lakehouse design']}],governance:{name:'Executive steering committee',text:'Bi-weekly alignment'}});
  add({type:'comparison',title:'Internal BI versus external data monetization APIs',rows:[{label:'Latency',left:'Seconds to minutes',right:'Sub-second'},{label:'Access',left:'Departmental RBAC',right:'Multi-tenant API keys'},{label:'Serving store',left:'BigQuery',right:'Cloud Bigtable'}],columns:['Aspect','Internal BI analytics','External monetization APIs']});
  add({type:'table',title:'Google Cloud Platform capabilities mapped to needs',columns:['Need','Legacy siloed tools','Point cloud solutions','Google Cloud fabric'],rows:[['Ingestion','Manual scripts','Separate ETL tool','Datastream and Pub/Sub'],['Governance','Spreadsheets','Separate catalog','Dataplex'],['BI','Many tools','One BI tool','Looker']]});
  add({type:'cards',title:'Self-service analytics consumption personas',items:[{title:'Looker dashboards',audience:'Executives',needs:'Governed KPIs in one place'},{title:'Conversational BI',audience:'Analysts',needs:'Ask questions in plain language'},{title:'Vertex AI Workbench',audience:'Data scientists',needs:'Notebook access to governed data'},{title:'Cloud Run APIs',audience:'Product teams',needs:'Data in their apps'}]});
  add({type:'bullets',title:'Immediate mobilization actions for week one',points:['Conduct project kickoff workshops to finalize objectives and KPIs.','Establish secure access controls and sandbox environments.','Begin discovery of data sources, schemas and pipelines.','Lock governance cadences with the client team.'],takeaway:'This executive action plan outlines the four immediate steps required in week one.'});
  add({type:'cards',title:'Value realization and business KPI framework',items:[{title:'Pipeline SLA latency',text:'Track end-to-end ingestion-to-serving latency.'},{title:'Data accuracy',text:'Measure automated parity pass rates.'},{title:'Unit compute cost per query',text:'Monitor average slot consumption.'},{title:'Self-service adoption',text:'Quantify daily active users.'}]});
  add({type:'bullets',title:'Zero-trust data security and privacy controls',items:[{title:'Identity and access governance',points:['Role-based access via Cloud IAM','Column-level masking','Row-level filters']},{title:'Infrastructure protection',points:['CMEK via Cloud KMS','VPC Service Controls','Audit logs']}]});
  add({type:'team',title:'RACI responsibility matrix across workstreams',items:[{title:'66degrees delivery pod',points:['Platform provisioning: author Terraform modules','Source extraction: build ingestion connectors']},{title:'ZoomInfo stakeholders',points:['Platform provisioning: approve IAM policies','Source extraction: grant credentials']}]});
  return S;
}
module.exports={plan};
